import { unstable_after } from 'next/server'
import { headers } from 'next/headers'

async function logPageView(url: string) {
  const analyticsService = {
    track: (event: string, data: object) => {
      console.log(`[Analytics] Event: ${event}`, { url, ...data, timestamp: new Date().toISOString() })
    }
  }
  analyticsService.track('page_view', { path: url })
}

export default function Home() {
  const headersList = headers()
  const pathname = headersList.get('x-invoke-path') || '/'

  unstable_after(() => {
    logPageView(pathname)
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Please implement page view logging that doesn&apos;t block the response.</p>
    </main>
  )
}

